<?php declare(strict_types=1);require_once __DIR__.'/../includes/bootstrap.php';require_once __DIR__.'/../includes/catalog.php';$user=lh_user();if(!$user){header('Location:/creator-ai/auth/google-login.php');exit;}$rows=[];try{if(lh_has_column($db,'learning_lessons','chapter_id')&&$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='learning_chapters'")->fetchColumn()){$sql="SELECT p.*,l.title lesson_title,c.title course_title FROM learning_progress p JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_chapters ch ON ch.id=l.chapter_id JOIN learning_courses c ON c.id=ch.course_id WHERE p.user_id=? ORDER BY p.updated_at DESC";}else{$sql="SELECT p.*,l.title lesson_title,c.title course_title FROM learning_progress p JOIN learning_lessons l ON l.id=p.lesson_id JOIN learning_courses c ON c.id=l.course_id WHERE p.user_id=? ORDER BY p.updated_at DESC";}$q=$db->prepare($sql);$q->execute([(int)$user['id']]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){error_log($e->getMessage());}$lh_page_title='My Learning';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/navbar.php';?><div class="container-fluid"><div class="row"><div class="col-lg-3 col-xl-2 p-0"><?php include __DIR__.'/../includes/sidebar.php';?></div><main class="col-lg-9 col-xl-10 py-4 py-lg-5"><div class="container-fluid"><div class="lh-hero p-4 mb-4"><div class="small text-primary fw-bold">My Learning</div><h1 class="h2 fw-bold mt-2">Welcome, <?=lh_h($user['name']??'Learner')?>.</h1><p class="text-secondary mb-0">Track the lessons you have completed and continue where you left off.</p></div><div class="vstack gap-3"><?php foreach($rows as $r):?><div class="lh-card p-4"><div class="d-flex justify-content-between gap-3"><div><strong><?=lh_h($r['lesson_title'])?></strong><div class="small text-secondary mt-1"><?=lh_h($r['course_title'])?></div></div><span class="small fw-bold"><?=number_format((int)$r['progress_percent'])?>%</span></div><div class="progress mt-3" style="height:8px"><div class="progress-bar" style="width:<?=min(100,(int)$r['progress_percent'])?>%"></div></div></div><?php endforeach;if(!$rows):?><div class="alert alert-light border">No progress yet. <a href="/learning-hub/courses.php" data-spa>Start a course →</a></div><?php endif;?></div></div></main></div></div><?php include __DIR__.'/../includes/footer.php';?><script src="/learning-hub/assets/js/app.js"></script><script src="/learning-hub/assets/js/router.js"></script>